/**
 * Conditions accepted by `where(...)`.
 *
 * A query or view call supplies an input pattern. Its optional `.is(...)`
 * pattern tests output fields with literals or bound variables and binds new
 * variables. A call without `.is(...)` checks only whether a matching row
 * exists. `.is.not(...)` tests that the stated output fields differ.
 *
 * `no(line)` requires zero matching rows. `whether(line)` keeps the current
 * match when the query or view returns no row and assigns `null` to variables
 * that line would have bound. Built-in comparisons and named computations add
 * closed conditions. Advanced code may use `custom(...)`.
 */
import type { ComputationFn, ComputationInput, ComputationRef, FusedComputation } from "./computations.ts";
import type { ActionTriggerPattern, InstrumentedQuery, Mapping } from "../reactions/types.ts";
import type { ReadLine, RelationView, ViewReadLine } from "./lines.ts";
import type { FormerUse, FusedFormer } from "./former-nodes.ts";
import type { ExactPattern, InputPattern } from "./type-inference.ts";
/** The query or view used by one read operation. */
interface LineRef {
    readonly query?: InstrumentedQuery;
    readonly view?: RelationView;
}
/** A read whose output pattern binds or tests fields and whose `not` pattern tests differences. */
export interface FindOp extends LineRef {
    readonly op: "find";
    readonly in: Mapping;
    readonly out: Mapping;
    readonly not?: Mapping;
}
/** A read that succeeds only when no row matches. */
interface NoOp extends LineRef {
    readonly op: "no";
    readonly in: Mapping;
    readonly out: Mapping;
}
/** A read that assigns matched outputs or assigns `null` when no row matches. */
interface WhetherOp extends LineRef {
    readonly op: "whether";
    readonly in: Mapping;
    readonly out: Mapping;
}
/** A closed line over a named computation; failing rows are dropped. */
interface HoldsOp {
    readonly op: "holds";
    readonly fused: FusedComputation;
}
/** A vocabulary-owned calculation, bound whole or projected through an output pattern. */
interface ComputeOp {
    readonly op: "compute";
    readonly computation: ComputationRef;
    readonly in: Mapping;
    readonly out: symbol | Mapping;
}
/** An opaque escape with a declared positional footprint. */
export interface CustomOp {
    readonly op: "custom";
    readonly name: string;
    readonly fn: (...args: unknown[]) => unknown | Promise<unknown>;
    readonly in: readonly symbol[];
    readonly out: readonly symbol[];
}
export type WhereOp = FindOp | NoOp | WhetherOp | HoldsOp | ComputeOp | CustomOp;
/**
 * A non-consuming read of the flow's record: the pattern stood earlier in
 * this causal tree — one row per matching occurrence, nothing consumed (the
 * double-fire guard belongs to the trigger alone). Built by
 * `earlier(action, in, out?)` (in `words.ts`, which owns action patterns);
 * evaluated by the engine, since it reads the flow index.
 */
export interface EarlierOp {
    readonly op: "earlier";
    readonly pattern: ActionTriggerPattern;
}
/** Bind one fresh variable to the instant of the current causal flow. */
export interface NowOp {
    readonly op: "now";
    readonly out: symbol;
}
/** A where op as a reaction's `.where(...)` accepts it, including flow-owned reads. */
export type AnyWhereOp = WhereOp | EarlierOp | NowOp;
/** A condition accepted by `where(...)`: an operation, read line, or named computation. */
export type Condition = AnyWhereOp | ReadLine | FusedComputation;
/** Brand an op constructed by the reaction authoring words. */
export declare function brandWhereOp<T extends object>(op: T): T;
/**
 * Accept one condition in `where(...)`, whatever its spelling: an op
 * passes through, a plain line lowers to `find`, a fused computation to
 * `holds`, a sentence view to its existence line.
 */
export declare function conditionOp(value: Condition, site: string): AnyWhereOp;
/** Whether a value is accepted by `where(...)`. */
export declare function isCondition(value: unknown): value is Condition;
/** Require that the query or view return no matching row. The line cannot bind new variables. */
export declare function no(line: ReadLine): NoOp;
/** Keep the current match when no row exists and assign `null` to the line's new variables. */
export declare function whether(line: ViewReadLine): WhetherOp;
export declare function whether(line: ReadLine): WhetherOp;
export declare function whether(fused: FusedFormer): FormerUse;
type ComputationOutput<Fn extends ComputationFn> = Awaited<ReturnType<Fn>>;
type ProjectedOutputValue<Value> = Value | symbol | (Value extends readonly (infer Item)[] ? readonly ProjectedOutputValue<Item>[] : Value extends object ? {
    readonly [Key in keyof Value]?: ProjectedOutputValue<Value[Key]>;
} : never);
type ComputationOutputPattern<Fn extends ComputationFn> = ComputationOutput<Fn> extends readonly unknown[] ? never : ComputationOutput<Fn> extends object ? {
    readonly [Key in keyof ComputationOutput<Fn>]?: ProjectedOutputValue<ComputationOutput<Fn>[Key]>;
} : never;
/** Bind a calculation's whole result, or project a record result through an output pattern. */
export declare function compute<Fn extends ComputationFn, const Input extends InputPattern<ComputationInput<Fn>>, Out extends symbol>(computation: ComputationRef<Fn>, input: ExactPattern<ComputationInput<Fn>, Input>, out: Out): ComputeOp;
export declare function compute<Fn extends ComputationFn, const Input extends InputPattern<ComputationInput<Fn>>, const Output extends ComputationOutputPattern<Fn>>(computation: ComputationRef<Fn>, input: ExactPattern<ComputationInput<Fn>, Input>, output: ExactPattern<ComputationOutput<Fn>, Output>): ComputeOp;
/**
 * An opaque function with a declared footprint:
 * which variables it reads (positional args) and which it writes (one value
 * per out variable; a single out binds the return value directly).
 */
export declare function custom(fn: (...args: never[]) => unknown | Promise<unknown>, input: readonly symbol[], output: readonly symbol[]): CustomOp;
export {};
